def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_my, last_op = history[-1]

    op_c = 0
    my_c = 0
    my_score = 0
    op_score = 0
    for a, b in history:
        if a == 'C':
            my_c += 1
        if b == 'C':
            op_c += 1
        if a == 'C':
            if b == 'C':
                my_score += 3
                op_score += 3
            else:
                op_score += 5
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                op_score += 1

    op_d = n - op_c
    my_d = n - my_c

    recent_len = 10 if n >= 10 else n
    recent_start = n - recent_len
    recent_c = 0
    for i in range(recent_start, n):
        if history[i][1] == 'C':
            recent_c += 1

    recent_rate = recent_c / recent_len
    total_rate = op_c / n

    streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            streak += 1
        else:
            break

    if recent_rate < 0.30 or (n >= 12 and recent_c <= 4):
        return 'D'

    if last_op == 'D':
        if recent_rate < 0.35:
            return 'D'

        p = 0.14 + 0.34 * total_rate + 0.44 * recent_rate

        if streak == 1:
            p += 0.07
            if total_rate >= 0.90 and recent_rate >= 0.90:
                p = 0.88
        elif streak == 2:
            p -= 0.07
            if last_my == 'D' and total_rate >= 0.80:
                if p < 0.70:
                    p = 0.70
        elif streak == 3:
            p -= 0.18
            if last_my == 'D' and total_rate >= 0.80:
                if p < 0.55:
                    p = 0.55
        else:
            p -= 0.28
            if total_rate < 0.70:
                p = 0.06

        if last_my == 'D':
            p += 0.12
        if op_d > my_c:
            p -= 0.08
        if my_score + 8 < op_score:
            p -= 0.12
        if my_score > op_score + 25:
            p += 0.05

        if p < 0.05:
            p = 0.05
        if p > 0.93:
            p = 0.93

        if rng.random() < p:
            return 'C'
        return 'D'

    remaining = 100 - n
    p_exp = 0.0

    if op_d == 0:
        if my_d == 0:
            p_exp = 0.02
            if n >= 7:
                p_exp += 0.03
            if n >= 25:
                p_exp += 0.04
            if n >= 60:
                p_exp += 0.05
            if remaining <= 10:
                p_exp += 0.08
        else:
            if last_my == 'D':
                if my_d >= 4:
                    p_exp = 0.52
                elif my_d >= 2:
                    p_exp = 0.40
                else:
                    p_exp = 0.08
                if recent_c == recent_len:
                    p_exp += 0.10
                if remaining <= 8:
                    p_exp += 0.20
            else:
                if my_d >= 4:
                    p_exp = 0.74
                else:
                    p_exp = 0.66
                if recent_c == recent_len:
                    p_exp += 0.10
                if remaining <= 8:
                    p_exp += 0.20

            if p_exp > 0.88:
                p_exp = 0.88

        if rng.random() < p_exp:
            return 'D'
    else:
        if recent_c >= 9 and total_rate >= 0.85:
            p_exp = 0.04
        elif recent_c >= 7:
            p_exp = 0.01
        else:
            p_exp = 0.0

        if my_score + 8 < op_score:
            p_exp += 0.25
        if remaining <= 8 and recent_c >= 7:
            p_exp += 0.15
        if op_d <= max(1, n // 8) and recent_c >= 9:
            p_exp += 0.08

        if p_exp > 0.50:
            p_exp = 0.50

        if rng.random() < p_exp:
            return 'D'

    return 'C'
